const now     = new Date();
const weekAgo = new Date(now - 7  * 24 * 60 * 60 * 1000);
const _90ago  = new Date(now - 90 * 24 * 60 * 60 * 1000);

return [{
  json: {
    run_date:      now.toISOString().slice(0, 10),
    week_start:    weekAgo.toISOString().slice(0, 10),
    window_90d:    _90ago.toISOString().slice(0, 10),
    report_label:  `Week of ${weekAgo.toISOString().slice(0, 10)}`
  }
}];

// Collect results from all 5 parallel queries into one context object
const icpRows       = $items('Query — ICP Conversion Rates').map(i => i.json);
const seniorityRows = $items('Query — Seniority Conversion').map(i => i.json);
const seqRows       = $items('Query — Sequence Performance').map(i => i.json);
const variantRows   = $items('Query — Variant Performance').map(i => i.json);
const weeklyRow     = $items('Query — Weekly Summary')[0]?.json || {};
const ctx           = $items('Set Run Context')[0].json;

// Format tables as compact text for the LLM prompt
const fmtTable = (rows, cols) => {
  if (!rows || rows.length === 0) return 'No data for this period.';
  const header = cols.join(' | ');
  const lines  = rows.map(r => cols.map(c => String(r[c] ?? '-')).join(' | '));
  return [header, ...lines].join('\n');
};

const icpTable = fmtTable(icpRows, ['industry','total_leads','reply_rate','meeting_rate','win_rate']);
const senTable = fmtTable(seniorityRows, ['seniority','total_leads','reply_rate','meeting_rate']);
const seqTable = fmtTable(seqRows, ['sequence_step','total_sent','replies','reply_rate','meetings']);
const varTable = fmtTable(variantRows, ['variant_group','sent','reply_rate','meeting_rate']);

const promptData = `
REPORTING PERIOD: ${ctx.report_label}

WEEKLY SUMMARY:
Emails sent: ${weeklyRow.emails_sent || 0}
Replies: ${weeklyRow.replies || 0} (${weeklyRow.overall_reply_rate || 0}% reply rate)
Meetings booked: ${weeklyRow.meetings_booked || 0}
Unique leads touched: ${weeklyRow.unique_leads_touched || 0}
Open escalations: ${weeklyRow.open_escalations || 0}
Signals detected: ${weeklyRow.signals_detected || 0}

INDUSTRY CONVERSION (last 90 days):
${icpTable}

TITLE/SENIORITY CONVERSION (last 90 days):
${senTable}

SEQUENCE STEP PERFORMANCE (last 90 days):
${seqTable}

A/B VARIANT PERFORMANCE (last 90 days):
${varTable}
`.trim();

return [{
  json: {
    ...ctx,
    prompt_data:     promptData,
    weekly_summary:  weeklyRow,
    icp_rows:        icpRows,
    seniority_rows:  seniorityRows,
    seq_rows:        seqRows,
    variant_rows:    variantRows
  }
}];

const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let insights = {};
try {
  const s = raw.indexOf('{'); const e = raw.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('no JSON');
  insights = JSON.parse(raw.slice(s, e + 1));
} catch(_) {
  insights = {
    executive_summary:  'Analytics run completed. See data tables for details.',
    top_insights:       ['Data available but AI summary failed — review tables directly.'],
    winning_segments:   [],
    underperforming:    [],
    recommendations:    ['Review industry conversion table', 'Check sequence step performance', 'Compare A/B variants'],
    best_sequence_step: 'unknown',
    variant_winner:     'inconclusive'
  };
}

const ctx = $items('Merge Query Results')[0].json;
const w   = ctx.weekly_summary || {};

// Format Slack Block Kit sections
const bulletList = (arr) => (arr || []).map(x => `• ${x}`).join('\n');

const insightLines   = bulletList(insights.top_insights);
const winLines       = bulletList(insights.winning_segments);
const loseLines      = bulletList(insights.underperforming);
const recLines       = (insights.recommendations || []).map((r, i) => `${i+1}. ${r}`).join('\n');

// ICP table formatted for Slack (top 5 rows)
const icpSlack = (ctx.icp_rows || []).slice(0, 5)
  .map(r => `• *${r.industry || '?'}*: ${r.reply_rate || 0}% reply | ${r.meeting_rate || 0}% meeting (n=${r.total_leads})`)
  .join('\n') || 'No data';

// Sequence table for Slack
const seqSlack = (ctx.seq_rows || []).slice(0, 5)
  .map(r => `• Step ${r.sequence_step}: ${r.reply_rate || 0}% reply rate (${r.replies || 0}/${r.total_sent || 0})`)
  .join('\n') || 'No data';

return [{
  json: {
    ...ctx,
    insights,
    insight_lines:   insightLines,
    win_lines:       winLines,
    lose_lines:      loseLines,
    rec_lines:       recLines,
    icp_slack:       icpSlack,
    seq_slack:       seqSlack,
    emails_sent:     w.emails_sent     || 0,
    replies:         w.replies         || 0,
    meetings_booked: w.meetings_booked || 0,
    reply_rate:      w.overall_reply_rate || 0,
    escalations:     w.open_escalations  || 0,
    signals:         w.signals_detected  || 0
  }
}];

