parameters.functionCode:
// ── ICP weight recalibration ─────────────────────────────────────────────
// For each client, adjust industry weights in icp_config proportionally
// to observed win rates over the last 90 days.
//
// Strategy: normalise win_rate across industries to sum to 1.0,
// then blend 80% existing weight + 20% observed rate (conservative update).
// This prevents wild swings from small sample sizes.

const icpRows   = $items('Query — ICP Conversion Rates').map(i => i.json);
const blendAlpha = 0.20;   // 20% new data, 80% existing weights

// Group by client_id
const byClient = {};
for (const row of icpRows) {
  if (!row.client_id) continue;
  if (!byClient[row.client_id]) byClient[row.client_id] = [];
  byClient[row.client_id].push(row);
}

const updates = [];

for (const [clientId, rows] of Object.entries(byClient)) {
  // Compute normalized win rates (sum to 1.0)
  const totalWinRate = rows.reduce((s, r) => s + parseFloat(r.win_rate || 0), 0);
  if (totalWinRate === 0) continue;   // no wins yet — skip recalibration

  const industryWeights = {};
  for (const row of rows) {
    const normRate = parseFloat(row.win_rate || 0) / totalWinRate;
    industryWeights[row.industry] = Math.round(normRate * 100) / 100;
  }

  updates.push({ clientId, industryWeights });
}

// If nothing to update, pass through
if (updates.length === 0) {
  return [{ json: { recalibration_skipped: true, reason: 'no wins data' } }];
}

// Return one item per client that needs updating
return updates.map(u => ({
  json: {
    client_id:        u.clientId,
    industry_weights: JSON.stringify(u.industryWeights),
    blend_alpha:      blendAlpha,
    recalibrated_at:  new Date().toISOString()
  }
}));

